#include <Arduino.h>

const uint8_t ledPins[3] = {2, 3, 4};
const uint8_t dataPin = A0;
const uint8_t latchPin = A1;
const uint8_t clockPin = A2;
const uint8_t digits[4] = {0x3f, 0x06, 0x5b, 0x4f};
unsigned long lastUpdate;

void showCount(uint8_t count) {
  digitalWrite(latchPin, LOW);
  shiftOut(dataPin, clockPin, MSBFIRST, (uint8_t)~digits[count]);
  digitalWrite(latchPin, HIGH);
}

void selectLEDs() {
  uint8_t count = (uint8_t)random(4);
  uint8_t order[3] = {0, 1, 2};
  for (uint8_t i = 2; i > 0; --i) {
    uint8_t j = (uint8_t)random(i + 1);
    uint8_t temp = order[i];
    order[i] = order[j];
    order[j] = temp;
  }
  uint8_t mask = 0;
  for (uint8_t i = 0; i < count; ++i) mask |= (1 << order[i]);
  for (uint8_t i = 0; i < 3; ++i)
    digitalWrite(ledPins[i], (mask & (1 << i)) ? HIGH : LOW);
  showCount(count);
}

void setup() {
  for (uint8_t i = 0; i < 3; ++i) {
    digitalWrite(ledPins[i], LOW);
    pinMode(ledPins[i], OUTPUT);
  }
  pinMode(dataPin, OUTPUT);
  pinMode(clockPin, OUTPUT);
  pinMode(latchPin, OUTPUT);
  digitalWrite(clockPin, LOW);
  showCount(0);
  randomSeed(analogRead(A3));
  lastUpdate = millis();
}

void loop() {
  unsigned long now = millis();
  if (now - lastUpdate >= 2000UL) {
    lastUpdate += 2000UL;
    selectLEDs();
  }
}
